preConditionHook:
// THE EXPANDING CORRECTION. The second leg of the correction has run beyond
// the FIRST leg's extreme: the running low since the last counted bar is
// below the low retained when the count first reached 1. Brooks: 'bears who
// shorted the first up leg will add as soon as the second leg up goes above
// the high of the first leg up.'
//
// THE COUNTER IS THE SETTLED ONE (Ranges ch17, R17-01), inlined here as
// everywhere -- see HighLowBarCount for the full commentary. Two of the three
// values this rule needs are already retained by it (the running extreme
// since the last counted bar, and the counted bar's own extreme); the one
// addition is firstLegLow / firstLegHigh, latched when the count advances to
// 1 and left alone until the next cycle. Every cycle passes through count 1,
// so by the time the count reaches 2 the latch always holds a real price.
//
// WHY THIS IS NOT THE COUNTER'S OWN ADVANCE GUARD: the guard asks for a new
// low since the LAST COUNTED bar, this asks for one beyond the FIRST leg's
// extreme. At the advance from 1 to 2 the two coincide exactly, because the
// last counted bar IS the count-1 bar; from count 3 on they diverge, and the
// shallow later leg is exactly the case Brooks is separating. The literal 2
// is structural -- the rule is about the SECOND leg -- so it is not an input.
//
// Distinct from LegCountAtLeast, which only asks HOW MANY legs there have
// been, and from HighLowBarCount, which fires on the signal bar itself.
priorHigh = high[1];
priorLow = low[1];
for (int i = 2; i <= (int)resetLookback; ++i) {
    if (el_gt(high[i], priorHigh)) priorHigh = high[i];
    if (el_lt(low[i], priorLow)) priorLow = low[i];
}
if (el_gt(close[0], priorHigh)) {
    highCount = 0;
} else {
    if (el_lt(low[0], minLowSince)) minLowSince = low[0];
    if (el_gt(high[0], high[1]) && (highCount == 0 || el_lt(minLowSince, signalLow))) {
        highCount = highCount + 1;
        if (highCount > 4) highCount = 4;
        signalLow = low[0];
        minLowSince = low[0];
        if (highCount == 1) firstLegLow = low[0];
    }
}
if (el_lt(close[0], priorLow)) {
    lowCount = 0;
} else {
    if (el_gt(high[0], maxHighSince)) maxHighSince = high[0];
    if (el_lt(low[0], low[1]) && (lowCount == 0 || el_gt(maxHighSince, signalHigh))) {
        lowCount = lowCount + 1;
        if (lowCount > 4) lowCount = 4;
        signalHigh = high[0];
        maxHighSince = high[0];
        if (lowCount == 1) firstLegHigh = high[0];
    }
}
